# Nginx as an L7 reverse proxy: routes by path, terminates TLS, adds headers
upstream api { server 10.0.2.11:8080; server 10.0.2.12:8080; }

server {
  listen 443 ssl;
  server_name shop.example.com;
  ssl_certificate     /etc/ssl/shop.crt;
  ssl_certificate_key /etc/ssl/shop.key;

  location /api/ {
    proxy_pass http://api;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  }
  location / { root /var/www/shop; }   # static files served directly
}
# An L4 balancer only sees IP:port, so it cannot route /api/ differently from /.

server {
    listen 443 ssl;
    server_name api.shop.vn;
    ssl_certificate     /etc/letsencrypt/live/api.shop.vn/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.shop.vn/privkey.pem;
    client_max_body_size 10m;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    location /ws/ {                       # WebSocket
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade    $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

