# environments/prod/main.tf — one module, different inputs per environment
terraform {
  backend "s3" {
    bucket = "acme-tf-state"
    key    = "prod/network.tfstate"
    region = "ap-southeast-1"
  }
}

module "network" {
  source     = "git::https://github.com/acme/tf-modules.git//network?ref=v1.4.0"  # pinned version
  cidr_block = "10.20.0.0/16"
  az_count   = 3
}

